-- Banco estruturado de perguntas de Neuroanatomia a partir da folha pessoal validada.
-- A origem é mantida como metadado; não são guardados nomes, emails ou identificadores de estudantes.
INSERT OR IGNORE INTO app_module_settings (module_key, enabled, updated_at) VALUES
  ('question_bank', 1, unixepoch() * 1000),
  ('question_bank.neuroanatomia', 1, unixepoch() * 1000);

CREATE TABLE IF NOT EXISTS question_bank_sources (
  id TEXT PRIMARY KEY,
  curricular_unit_id TEXT NOT NULL REFERENCES curricular_units(id) ON DELETE CASCADE,
  source_kind TEXT NOT NULL CHECK (source_kind IN ('google_sheet', 'local_file')),
  label TEXT NOT NULL,
  locator TEXT NOT NULL,
  revision_label TEXT NOT NULL DEFAULT '',
  source_row_count INTEGER NOT NULL CHECK (source_row_count >= 0),
  imported_count INTEGER NOT NULL CHECK (imported_count >= 0),
  published_count INTEGER NOT NULL CHECK (published_count >= 0),
  review_count INTEGER NOT NULL CHECK (review_count >= 0),
  coverage_json TEXT NOT NULL DEFAULT '{}',
  verification_status TEXT NOT NULL CHECK (verification_status IN ('verified', 'review', 'archived')),
  created_by TEXT NOT NULL REFERENCES users(id) ON DELETE RESTRICT,
  created_at INTEGER NOT NULL,
  updated_at INTEGER NOT NULL,
  UNIQUE (curricular_unit_id, locator)
);

CREATE TABLE IF NOT EXISTS question_bank_topics (
  id TEXT PRIMARY KEY,
  curricular_unit_id TEXT NOT NULL REFERENCES curricular_units(id) ON DELETE CASCADE,
  source_id TEXT NOT NULL REFERENCES question_bank_sources(id) ON DELETE CASCADE,
  chapter_number TEXT NOT NULL,
  title TEXT NOT NULL,
  sort_order INTEGER NOT NULL DEFAULT 0 CHECK (sort_order >= 0),
  created_by TEXT NOT NULL REFERENCES users(id) ON DELETE RESTRICT,
  updated_by TEXT NOT NULL REFERENCES users(id) ON DELETE RESTRICT,
  created_at INTEGER NOT NULL,
  updated_at INTEGER NOT NULL,
  UNIQUE (source_id, chapter_number)
);

CREATE TABLE IF NOT EXISTS question_bank_items (
  id TEXT PRIMARY KEY,
  curricular_unit_id TEXT NOT NULL REFERENCES curricular_units(id) ON DELETE CASCADE,
  topic_id TEXT NOT NULL REFERENCES question_bank_topics(id) ON DELETE CASCADE,
  source_id TEXT NOT NULL REFERENCES question_bank_sources(id) ON DELETE CASCADE,
  external_key TEXT NOT NULL,
  prompt TEXT NOT NULL,
  options_text TEXT NOT NULL DEFAULT '',
  answer_indicated TEXT NOT NULL DEFAULT '',
  answer_text TEXT NOT NULL DEFAULT '',
  source_original TEXT NOT NULL DEFAULT '',
  anatomical_justification TEXT NOT NULL DEFAULT '',
  response_type TEXT NOT NULL DEFAULT 'short_answer' CHECK (response_type IN ('short_answer', 'multiple_choice', 'case')),
  source_subtopic TEXT NOT NULL DEFAULT '',
  source_academic_year TEXT NOT NULL DEFAULT '',
  source_page TEXT NOT NULL DEFAULT '',
  source_question TEXT NOT NULL DEFAULT '',
  source_assessment TEXT NOT NULL DEFAULT '',
  source_session TEXT NOT NULL DEFAULT '',
  validation_state TEXT NOT NULL DEFAULT 'review' CHECK (validation_state IN ('VALIDADO', 'review', '')),
  confidence TEXT NOT NULL DEFAULT '',
  status TEXT NOT NULL DEFAULT 'review' CHECK (status IN ('review', 'published', 'archived')),
  review_note TEXT NOT NULL DEFAULT '',
  sort_order INTEGER NOT NULL DEFAULT 0 CHECK (sort_order >= 0),
  created_by TEXT NOT NULL REFERENCES users(id) ON DELETE RESTRICT,
  updated_by TEXT NOT NULL REFERENCES users(id) ON DELETE RESTRICT,
  created_at INTEGER NOT NULL,
  updated_at INTEGER NOT NULL,
  UNIQUE (source_id, external_key)
);

CREATE INDEX IF NOT EXISTS idx_question_bank_listing ON question_bank_items(curricular_unit_id, status, topic_id, sort_order, id);
CREATE INDEX IF NOT EXISTS idx_question_bank_search ON question_bank_items(curricular_unit_id, status, topic_id);

DROP TABLE IF EXISTS _seed_neuro_question_bank_context;
CREATE TABLE _seed_neuro_question_bank_context (unit_id TEXT NOT NULL, actor_id TEXT NOT NULL);
INSERT INTO _seed_neuro_question_bank_context (unit_id, actor_id)
SELECT cu.id, COALESCE(
  (SELECT id FROM users WHERE status='active' AND (role='admin' OR commission_department='management') ORDER BY created_at LIMIT 1),
  (SELECT id FROM users WHERE status='active' ORDER BY created_at LIMIT 1)
) FROM curricular_units cu WHERE cu.code='NEURO' AND cu.active=1
  AND COALESCE((SELECT id FROM users WHERE status='active' AND (role='admin' OR commission_department='management') ORDER BY created_at LIMIT 1), (SELECT id FROM users WHERE status='active' ORDER BY created_at LIMIT 1)) IS NOT NULL;

-- Não marcar a migration como aplicada sem uma UC NEURO ativa e um ator técnico.
-- A inserção NULL é intencional: as colunas NOT NULL fazem a aplicação falhar
-- explicitamente, tal como nas cargas curriculares anteriores.
INSERT INTO _seed_neuro_question_bank_context (unit_id, actor_id)
SELECT NULL, NULL
WHERE NOT EXISTS (SELECT 1 FROM _seed_neuro_question_bank_context);

INSERT INTO question_bank_sources (id, curricular_unit_id, source_kind, label, locator, revision_label, source_row_count, imported_count, published_count, review_count, verification_status, created_by, created_at, updated_at)
SELECT 'source-neuro-drive-question-bank', unit_id, 'google_sheet', 'Compêndio geral de perguntas de Neuroanatomia — folha estruturada pessoal', '184x7c5w44eZJ5SsUlgUlDMKyOoUNvQGRH74YGvdETUQ', '2026-09', 1370, 1207, 890, 317, 'review', actor_id, unixepoch() * 1000, unixepoch() * 1000
