SELECT 'qb-neuro-item-Q-FMUP-0890', unit_id, 'qb-neuro-topic-11', 'source-neuro-drive-question-bank', 'Q-FMUP-0890', 'Relativamente ao mesencéfalo rostral, seleccione a opção falsa:

