SELECT 'qb-neuro-item-Q-FMUP-0954', unit_id, 'qb-neuro-topic-04', 'source-neuro-drive-question-bank', 'Q-FMUP-0954', 'Relativamente ao hipotálamo, seleccione a opção correcta:

