SELECT 'qb-neuro-item-Q-FMUP-0981', unit_id, 'qb-neuro-topic-11', 'source-neuro-drive-question-bank', 'Q-FMUP-0981', 'Relativamente ao diencéfalo assinale a afirmação incorrecta:

