SELECT 'qb-neuro-item-Q-FMUP-0985', unit_id, 'qb-neuro-topic-19', 'source-neuro-drive-question-bank', 'Q-FMUP-0985', 'Relativamente ao hipotálamo seleccione aafirmação correcta:

