SELECT 'qb-neuro-item-EX-NEURO-CAP01-010', unit_id, 'qb-neuro-topic-13', 'source-neuro-drive-question-bank', 'EX-NEURO-CAP01-010', 'Qual é a linha imaginária / plano que une o bordo inferior da órbita e o bordo superior do meato acústico externo?', 'Plano de Frankfurt (Plano horizontal orbitomeático).', 'short_answer', 'ADT 1 - Questão 52', 'Pergunta 52', 'Avaliação Diagnóstica Teórica (ADT)', 'published', '', 1186, actor_id, actor_id, unixepoch() * 1000, unixepoch() * 1000
