INSERT INTO _seed_neuro_question_bank_fields (external_key,options_text,answer_indicated,answer_text,response_type,source_subtopic,source_academic_year,source_page,source_question,source_assessment,source_session,validation_state,confidence,review_note) VALUES ('EX-NEURO-CAP01-020','N/A (Pergunta de Desenvolvimento)','Sinal de Battle; Fratura da fossa craniana posterior / porção mastoideia do temporal; Artéria auricular posterior.','Sinal de Battle. Fratura da fossa craniana posterior (osso temporal/occipital). Artéria auricular posterior (e veia emissária mastoideia).','case','1.6. Traumatologia Craniana: Fratura da Fossa Posterior e Sinal de Battle','2024/2025','Página 2','Caso 1','Casos Clínicos Neuroanatomia','Avaliação Prática','VALIDADO','ALTO','');
INSERT INTO _seed_neuro_question_bank_fields (external_key,options_text,answer_indicated,answer_text,response_type,source_subtopic,source_academic_year,source_page,source_question,source_assessment,source_session,validation_state,confidence,review_note) VALUES ('EX-NEURO-CAP02-001','N/A (Pergunta de Desenvolvimento)','a) Ectoderme, na superfície dorsal do embrião, anteriormente ao nó primitivo. Fatores indutores Shh e BMP. b) Placa neural invagina formando goteira neural e pregas que se fundem. Neuroporo anterior = abertura cranial; Neuroporo posterior = abertura caudal.','a) Ectoderme dorsal da linha média, anteriormente ao nó primitivo. O notocórdio atua como centro indutor primário libertando Shh e antagonistas de BMPs (noggina/cordina) que bloqueiam a sinalização epidérmica e induzem a neuroectoderme.
b) As margens laterais da placa elevam-se formando pregas neurais que delimitam uma goteira central; as pregas fundem-se na linha média formando o tubo neural cilíndrico. O neuroporo anterior representa a abertura cranial temporária (encerra ao dia 25) e o neuroporo posterior a abertura caudal (encerra ao dia 28).','short_answer','2.1. Indução Notocordal e Placa Neural','2025/2026','Página 1','Pergunta 1 (alíneas a e b)','Exame de Recurso','Recurso (11/02/2026)','VALIDADO','ALTO','');
INSERT INTO _seed_neuro_question_bank_fields (external_key,options_text,answer_indicated,answer_text,response_type,source_subtopic,source_academic_year,source_page,source_question,source_assessment,source_session,validation_state,confidence,review_note) VALUES ('EX-NEURO-CAP03-001','N/A (Pergunta de Desenvolvimento)','a) Lâmina VII; C8/T1 a L2/L3; Núcleo cuneiforme acessório. b) Feixe espinhocerebeloso posterior; Ipsilateral (não cruza); Pedúnculo cerebeloso inferior (corpo restiforme); Fibras musgosas.','a) Lâmina VII de Rexed, segmentos medulares C8/T1 a L2/L3. Homólogo no bolbo: Núcleo cuneiforme acessório (núcleo de von Monakow).
b) Feixe / Trato Espinocerebeloso Posterior (dorsal). Fibras estritamente ipsilaterais (não cruzam). Entram pelo Pedúnculo Cerebeloso Inferior (corpo restiforme) e terminam no córtex cerebeloso como Fibras Musgosas.','short_answer','3.3. Lâminas de Rexed e Núcleo de Clarke','2025/2026','Página 2','Pergunta 8 (alíneas a e b)','Exame de Recurso','Recurso (11/02/2026)','VALIDADO','ALTO','');
INSERT INTO _seed_neuro_question_bank_fields (external_key,options_text,answer_indicated,answer_text,response_type,source_subtopic,source_academic_year,source_page,source_question,source_assessment,source_session,validation_state,confidence,review_note) VALUES ('EX-NEURO-CAP03-002','N/A (Pergunta de Desenvolvimento)','a) Artéria radicular magna (de Adamkiewicz); Origem entre T8 e L2. b) Os cordões posteriores são irrigados pelas artérias espinhais posteriores; preservam-se a propriocepção consciente, tato fino e sensibilidade vibratória.','a) Artéria Radicular Magna (de Adamkiewicz), originada de artéria intercostal posterior ou lombar entre T8 e L2 (geralmente T9-T12 à esquerda).
b) Os cordões posteriores são supridos pelo sistema arterial das artérias espinhais posteriores; mantêm-se inalteradas a propriocepção consciente, a sensibilidade vibratória e o tato fino discriminativo.','short_answer','3.5. Vascularização Medular: Artéria de Adamkiewicz','2025/2026','Página 2','Pergunta 9 (alíneas a e b)','Exame de Recurso','Recurso (11/02/2026)','VALIDADO','ALTO','');
INSERT INTO _seed_neuro_question_bank_fields (external_key,options_text,answer_indicated,answer_text,response_type,source_subtopic,source_academic_year,source_page,source_question,source_assessment,source_session,validation_state,confidence,review_note) VALUES ('EX-NEURO-CAP04-001','N/A (Pergunta de Desenvolvimento)','a) Lábio rômbico; No metencéfalo: núcleos da ponte; No mielencéfalo: núcleo olivar inferior. b) Núcleos olivares inferiores; Fibras trepadoras / olivocerebelosas; Pedúnculo cerebeloso inferior.','a) Lábio Rômbico. Metencéfalo: Núcleos da Ponte (núcleos pônticos); Mielencéfalo: Complexo Olivar Inferior.
b) Complexo Nuclear Olivar Inferior (e núcleos arqueados). Dão origem às Fibras Olivocerebelosas / Trepadoras. Dirigem-se para o Pedúnculo Cerebeloso Inferior.','short_answer','4.1. Morfologia e Núcleos Pré-Cerebelosos','2025/2026','Página 1','Pergunta 2 (alíneas a e b)','Exame de Recurso','Recurso (11/02/2026)','VALIDADO','ALTO','');
INSERT INTO _seed_neuro_question_bank_fields (external_key,options_text,answer_indicated,answer_text,response_type,source_subtopic,source_academic_year,source_page,source_question,source_assessment,source_session,validation_state,confidence,review_note) VALUES ('EX-NEURO-CAP10-001','N/A (Pergunta de Desenvolvimento)','a) Núcleo supraquiasmático; Zona periventricular / anterior; Células ganglionares da retina; Melanopsina; Feixe retino-hipotalâmico. b) Glândula pineal (epífise); Melatonina; Diminui durante o dia e no verão.','a) Núcleo Supraquiasmático (subdivisão anterior / periventricular do hipotálamo). Células: Células ganglionares retinianas fotossensíveis. Pigmento: Melanopsina. Feixe: Trato Retino-Hipotalâmico.
b) Glândula Pineal (Epífise). Mediador: Melatonina. Secreção diminui durante o dia e no verão.','short_answer','10.3. Ritmos Circadianos e Núcleo Supraquiasmático','2025/2026','Página 1','Pergunta 5 (alíneas a e b)','Exame de Recurso','Recurso (11/02/2026)','VALIDADO','ALTO','');
INSERT INTO _seed_neuro_question_bank_fields (external_key,options_text,answer_indicated,answer_text,response_type,source_subtopic,source_academic_year,source_page,source_question,source_assessment,source_session,validation_state,confidence,review_note) VALUES ('EX-NEURO-CAP11-001','N/A (Pergunta de Desenvolvimento)','a) Hemisfério direito; Face medial, giro pré-central / lóbulo paracentral anterior, lobo frontal, Área 4 de Brodmann; Feixe corticoespinhal lateral. b) Artéria cerebral anterior; Ramos pericalosa e calosomarginal; Se caudal à curvatura cervical seria ipsilateral.','a) Hemisfério cerebral direito. Face medial do hemisfério, no lóbulo paracentral anterior / giro pré-central, no lobo frontal, correspondente à Área 4 de Brodmann (córtex motor primário). Feixe atingido: Trato corticoespinhal (piramidal).
b) Artéria Cerebral Anterior (ACA) direita. Ramos: Artéria pericalosa e artéria calosomarginal. Caudalmente à curvatura cervical (abaixo da decussação piramidal), o défice motor seria ipsilateral à lesão.','short_answer','11.1. Sulcos, Giros e Território Vascular','2025/2026','Página 3','Pergunta 16 (alíneas a e b)','Exame de Recurso','Recurso (11/02/2026)','VALIDADO','ALTO','');
INSERT INTO _seed_neuro_question_bank_fields (external_key,options_text,answer_indicated,answer_text,response_type,source_subtopic,source_academic_year,source_page,source_question,source_assessment,source_session,validation_state,confidence,review_note) VALUES ('EX-NEURO-CAP13-001','N/A (Pergunta de Desenvolvimento)','a) Síndrome de Klüver-Bucy; Amígdala e hipocampo. b) Perda do controlo inibitório sobre impulsos instintivos e perda da avaliação de adequação social dos estímulos.','a) Síndrome de Klüver-Bucy. Estruturas afetadas: Complexo nuclear da Amígdala e Formação Hipocampal (lobo temporal medial) bilateralmente.
b) A ablação da amígdala elimina a capacidade de associar estímulos sensoriais a recompensas ou punições aprendidas e anula o controlo inibitório sobre o hipotálamo, resultando na necessidade de exploração oral (hiperoralidade) por agnosia visual e na desinibição dos impulsos sexuais instintivos primários.','short_answer','13.3. Síndrome de Klüver-Bucy e Amígdala','2025/2026','Página 4','Pergunta 28 (alíneas a e b)','Exame de Recurso','Recurso (11/02/2026)','VALIDADO','ALTO','');
INSERT INTO _seed_neuro_question_bank_fields (external_key,options_text,answer_indicated,answer_text,response_type,source_subtopic,source_academic_year,source_page,source_question,source_assessment,source_session,validation_state,confidence,review_note) VALUES ('EX-NEURO-CAP14-001','N/A (Pergunta de Desenvolvimento)','a) O núcleo subtalâmico estimula o GPi que inibe o tálamo. A lesão subtalâmica desinibe o tálamo motor. b) O tálamo esquerdo ativa o córtex motor esquerdo, que cruza na decussação das pirâmides para controlar o hemicorpo direito.','a) O núcleo subtalâmico excita via glutamato o globo pálido interno (GPi) na via indireta. A sua lesão reduz a atividade do GPi, resultando na desinibição do tálamo motor ipsilateral (VA/VL) e consequente hiperestimulação do córtex motor.
b) O tálamo esquerdo desinibido hiperativa o córtex motor primário esquerdo; como o trato corticoespinhal lateral decussa no bolbo (decussação das pirâmides), os movimentos involuntários balísticos manifestam-se no lado contralateral (membros direitos).','short_answer','14.2. Circuitos Corticoestriatais e Hemibalismo','2025/2026','Página 3','Pergunta 21 (alíneas a e b)','Exame de Recurso','Recurso (11/02/2026)','VALIDADO','ALTO','');
INSERT INTO _seed_neuro_question_bank_fields (external_key,options_text,answer_indicated,answer_text,response_type,source_subtopic,source_academic_year,source_page,source_question,source_assessment,source_session,validation_state,confidence,review_note) VALUES ('EX-NEURO-CAP15-001','N/A (Pergunta de Desenvolvimento)','a) Buraco interventricular (de Monro); Limite anterior: coluna do fórnix; Limite posterior: tubérculo anterior do tálamo. b) Estrutura par: corpos mamilares; Estrutura ímpar: quiasma óptico / eminência média; Recesso: recesso infundibular; Estrutura intermural: adesão intertalâmica.','a) Buraco Interventricular (de Monro). Limite anterior: Coluna do fórnix; Limite posterior: Tubérculo anterior do tálamo.
b) Estrutura par no pavimento: Corpos mamilares; Estrutura ímpar: Quiasma óptico (ou tuber cinereum). Recesso do pavimento: Recesso infundibular. Estrutura intermural: Adesão intertalâmica (massa intermédia).','short_answer','15.3. Terceiro Ventrículo e Ventriculostomia','2025/2026','Página 2','Pergunta 7 (alíneas a e b)','Exame de Recurso','Recurso (11/02/2026)','VALIDADO','ALTO','');
INSERT INTO _seed_neuro_question_bank_fields (external_key,options_text,answer_indicated,answer_text,response_type,source_subtopic,source_academic_year,source_page,source_question,source_assessment,source_session,validation_state,confidence,review_note) VALUES ('EX-NEURO-CAP17-001','N/A (Pergunta de Desenvolvimento)','a) Direto: constrição pupilar no olho iluminado; Consensual: constrição pupilar no olho oposto. Aferente: nervo óptico (II); Eferente: nervo oculomotor (III). b) Luz no olho lesado: ambos abolidos; Luz no olho contralateral: ambos preservados.','a) Reflexo direto: miose pupilar no olho iluminado; Reflexo consensual: miose simultânea no olho contralateral. Via aferente: Nervo Óptico (II par); Via eferente: Nervo Oculomotor (III par craniano).
b) Ao iluminar o olho lesado: ambos os reflexos direto e consensual estão abolidos. Ao iluminar o olho contralateral normal: ambos os reflexos direto e consensual estão preservados.','short_answer','17.3. Reflexo Fotomotor Direto e Consensual','2025/2026','Página 3','Pergunta 17 (alíneas a e b)','Exame de Recurso','Recurso (11/02/2026)','VALIDADO','ALTO','');
INSERT INTO _seed_neuro_question_bank_fields (external_key,options_text,answer_indicated,answer_text,response_type,source_subtopic,source_academic_year,source_page,source_question,source_assessment,source_session,validation_state,confidence,review_note) VALUES ('EX-NEURO-CAP19-001','N/A (Pergunta de Desenvolvimento)','a) Fibras pré-ganglionares simpáticas mielinizadas; Coluna intermédio-lateral (T1-L2); Eferente visceral geral (EVG). b) Fibras pós-ganglionares simpáticas amielínicas; Gânglios da cadeia paravertebral; Medial ao branco; 14 a 15 pares de ramos brancos.','a) Fibras pré-ganglionares simpáticas mielinizadas (cor branca conferida pela mielina). Origem: Coluna Intermédio-Lateral da medula espinhal (Lâmina VII, T1-L2). Componente funcional: Eferente Visceral Geral (EVG).
b) Fibras pós-ganglionares simpáticas amielínicas (desprovidas de mielina). Origem: Gânglios paravertebrais do tronco simpático. Posição: Medial em relação ao ramo branco. Quantidade: Existem 14 a 15 pares de ramos comunicantes brancos.','short_answer','19.2. Ramos Comunicantes Brancos e Cinzentos','2025/2026','Página 4','Pergunta 23 (alíneas a e b)','Exame de Recurso','Recurso (11/02/2026)','VALIDADO','ALTO','');
UPDATE question_bank_items SET
  options_text=(SELECT s.options_text FROM _seed_neuro_question_bank_fields s WHERE s.external_key=question_bank_items.external_key),
  answer_indicated=(SELECT s.answer_indicated FROM _seed_neuro_question_bank_fields s WHERE s.external_key=question_bank_items.external_key),
  answer_text=(SELECT s.answer_text FROM _seed_neuro_question_bank_fields s WHERE s.external_key=question_bank_items.external_key),
  source_original=(SELECT s.source_original FROM _seed_neuro_question_bank_fields s WHERE s.external_key=question_bank_items.external_key),
  anatomical_justification=(SELECT s.anatomical_justification FROM _seed_neuro_question_bank_fields s WHERE s.external_key=question_bank_items.external_key),
  response_type=(SELECT s.response_type FROM _seed_neuro_question_bank_fields s WHERE s.external_key=question_bank_items.external_key),
  source_subtopic=(SELECT s.source_subtopic FROM _seed_neuro_question_bank_fields s WHERE s.external_key=question_bank_items.external_key),
  source_academic_year=(SELECT s.source_academic_year FROM _seed_neuro_question_bank_fields s WHERE s.external_key=question_bank_items.external_key),
  source_page=(SELECT s.source_page FROM _seed_neuro_question_bank_fields s WHERE s.external_key=question_bank_items.external_key),
  source_question=(SELECT s.source_question FROM _seed_neuro_question_bank_fields s WHERE s.external_key=question_bank_items.external_key),
  source_assessment=(SELECT s.source_assessment FROM _seed_neuro_question_bank_fields s WHERE s.external_key=question_bank_items.external_key),
  source_session=(SELECT s.source_session FROM _seed_neuro_question_bank_fields s WHERE s.external_key=question_bank_items.external_key),
  validation_state=(SELECT s.validation_state FROM _seed_neuro_question_bank_fields s WHERE s.external_key=question_bank_items.external_key),
  confidence=(SELECT s.confidence FROM _seed_neuro_question_bank_fields s WHERE s.external_key=question_bank_items.external_key),
  review_note=(SELECT s.review_note FROM _seed_neuro_question_bank_fields s WHERE s.external_key=question_bank_items.external_key)
WHERE question_bank_items.source_id='source-neuro-drive-question-bank';

-- A folha contém linhas rotuladas como validadas que ainda têm avisos de
-- truncamento, respostas genéricas ou opções de escolha múltipla sem texto.
-- Esses sinais são de moderação, não conteúdo publicável. Também ficam em
-- revisão as respostas reduzidas a uma referência/fragmento.
UPDATE question_bank_items
SET review_note=CASE
  WHEN response_type='multiple_choice'
    AND lower(trim(options_text)) NOT LIKE 'opções de resposta%'
    AND lower(trim(options_text)) NOT LIKE 'n/a%'
    AND instr(lower(options_text),'a)')>0
    AND instr(lower(options_text),'b)')>0
    AND lower(trim(review_note))='formato de escolha múltipla sem opções estruturadas; requer revisão.' THEN ''
  WHEN trim(review_note)<>'' THEN review_note
  WHEN trim(answer_text)='Resolução validada FMUP.' THEN 'Resposta validada de forma genérica; requer revisão antes da publicação.'
  WHEN response_type='multiple_choice' AND (
    lower(trim(options_text)) LIKE 'opções de resposta%'
    OR lower(trim(options_text)) LIKE 'n/a%'
    OR instr(lower(options_text),'a)')=0
    OR instr(lower(options_text),'b)')=0
  ) THEN 'Formato de escolha múltipla sem opções estruturadas; requer revisão.'
  WHEN (trim(answer_text)<>'' AND trim(answer_text) NOT GLOB '*[^0-9]*') OR trim(answer_text)='OS' THEN 'Resposta parece ser apenas referência ou fragmento; requer revisão.'
  ELSE review_note
END,
status=CASE
  WHEN (trim(review_note)<>'' AND NOT (
      response_type='multiple_choice'
      AND lower(trim(options_text)) NOT LIKE 'opções de resposta%'
      AND lower(trim(options_text)) NOT LIKE 'n/a%'
      AND instr(lower(options_text),'a)')>0
      AND instr(lower(options_text),'b)')>0
      AND lower(trim(review_note))='formato de escolha múltipla sem opções estruturadas; requer revisão.'
    ))
    OR trim(answer_text)='Resolução validada FMUP.'
    OR (response_type='multiple_choice' AND (
      lower(trim(options_text)) LIKE 'opções de resposta%'
      OR lower(trim(options_text)) LIKE 'n/a%'
      OR instr(lower(options_text),'a)')=0
      OR instr(lower(options_text),'b)')=0
    ))
    OR (trim(answer_text)<>'' AND trim(answer_text) NOT GLOB '*[^0-9]*')
    OR trim(answer_text)='OS'
  THEN 'review'
  ELSE 'published'
END
WHERE source_id='source-neuro-drive-question-bank';

UPDATE question_bank_sources
SET published_count=(SELECT COUNT(*) FROM question_bank_items WHERE source_id=question_bank_sources.id AND status='published'),
    review_count=(SELECT COUNT(*) FROM question_bank_items WHERE source_id=question_bank_sources.id AND status='review'),
    verification_status=CASE WHEN EXISTS (SELECT 1 FROM question_bank_items WHERE source_id=question_bank_sources.id AND status='review') THEN 'review' ELSE 'verified' END,
    coverage_json='{"rows":1370,"columns":18,"fields":{"subtopic":{"nonEmpty":1370,"distinct":154},"academicYear":{"nonEmpty":1370,"distinct":6},"assessmentType":{"nonEmpty":1370,"distinct":11},"session":{"nonEmpty":1370,"distinct":21},"questionNumber":{"nonEmpty":1370,"distinct":281},"page":{"nonEmpty":1370,"distinct":22},"prompt":{"nonEmpty":1370,"distinct":1362},"options":{"nonEmpty":1370,"distinct":6},"indicatedAnswer":{"nonEmpty":1370,"distinct":720},"validatedAnswer":{"nonEmpty":1370,"distinct":766},"validationState":{"nonEmpty":1370,"distinct":1},"warning":{"nonEmpty":1370,"distinct":105},"confidence":{"nonEmpty":1370,"distinct":1},"sourceOriginal":{"nonEmpty":0,"distinct":0},"anatomicalJustification":{"nonEmpty":0,"distinct":0}},"selection":{"excludedWarnings":163,"excludedDuplicates":0,"reviewPlaceholders":288,"reviewTruncations":27,"reviewFragments":17,"reviewTotal":317}}'
WHERE id='source-neuro-drive-question-bank';
